        """
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: string, mathematical expression using the cards
        :return: bool, True if the expression evaluates to 24, False otherwise
        """
        if expression == 'pass':
            return self.get_my_cards()

        # Count occurrences of digits in the expression
        statistic = {}
        for c in expression:
            if c.isdigit():
                statistic[c] = statistic.get(c, 0) + 1

        # Verify that the expression uses exactly the numbers provided in self.nums
        nums_used = statistic.copy()
        for num in self.nums:
            num_str = str(num)
            if nums_used.get(num_str, 0) > 0:
                nums_used[num_str] -= 1
            else:
                return False

        # Ensure no extra numbers were used
        if all(count == 0 for count in nums_used.values()):
            return self.evaluate_expression(expression)
        else:
            return False

    def evaluate_expression(self, expression):
        """
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: string, mathematical expression
        :return: bool, True if the expression evaluates to 24, False otherwise
        """
        try:
            # Using eval to calculate the result of the expression
            if eval(expression) == 24:
                return True
            else:
                return False
        except Exception:
            return False
